		[OpenTpwText.LoadingTextures] = new[] { "Updating textures in the background... {0} / {1}", "Opdaterer teksturer i baggrunden... {0} / {1}", "Textures worden op de achtergrond bijgewerkt... {0} / {1}", "Mise à jour des textures en arrière-plan... {0} / {1}", "Texturen werden im Hintergrund aktualisiert... {0} / {1}", "백그라운드에서 텍스처 갱신 중... {0} / {1}", "Aktualizacja tekstur w tle... {0} / {1}", "Actualizando texturas en segundo plano... {0} / {1}", "Uppdaterar texturer i bakgrunden... {0} / {1}" },
		[OpenTpwText.BuildingPark] = new[] { "Building the park...", "Bygger parken...", "Het park wordt gebouwd...", "Construction du parc...", "Der Park wird gebaut...", "공원 건설 중...", "Budowanie parku...", "Construyendo el parque...", "Bygger parken..." },
		[OpenTpwText.TexturePackHelp] = new[]
		{
			"Original: the game's own textures, selected by default. Enhanced (Clarity): the Clarity texture pack. Enhanced (legacy): the earlier choice. Keep playing while textures update in the background.",
			"Oprindelig: spillets egne teksturer, valgt som standard. Forbedret (Clarity): Clarity-pakken. Forbedret (tidligere): det tidligere valg. Spil videre, mens teksturerne opdateres i baggrunden.",
			"Origineel: de eigen textures van het spel, standaard geselecteerd. Verbeterd (Clarity): het Clarity-pakket. Verbeterd (eerder): de eerdere keuze. Speel verder terwijl de textures op de achtergrond worden bijgewerkt.",
			"D'origine : les textures du jeu, choisies par défaut. Amélioré (Clarity) : le pack Clarity. Amélioré (ancien) : le choix précédent. Continuez à jouer pendant la mise à jour en arrière-plan.",
			"Ursprünglich: die Texturen des Spiels, standardmäßig ausgewählt. Verbessert (Clarity): das Clarity-Paket. Verbessert (bisherig): die bisherige Auswahl. Weiterspielen, während die Texturen im Hintergrund aktualisiert werden.",
			"원본: 게임 자체 텍스처, 기본 선택입니다. 향상 (Clarity): Clarity 텍스처 팩입니다. 향상 (이전): 이전 선택입니다. 텍스처가 갱신되는 동안 계속 플레이할 수 있습니다.",
			"Oryginalne: tekstury gry, wybrane domyślnie. Ulepszone (Clarity): pakiet tekstur Clarity. Ulepszone (stare): poprzedni wybór. Graj dalej, gdy tekstury aktualizują się w tle.",
			"Original: las texturas propias del juego, elegidas por defecto. Mejorado (Clarity): el paquete de texturas Clarity. Mejorado (anterior): la opción anterior. Sigue jugando mientras las texturas se actualizan en segundo plano.",
			"Ursprunglig: spelets egna texturer, valda som standard. Förbättrad (Clarity): Clarity-paketet. Förbättrad (tidigare): det tidigare valet. Spela vidare medan texturerna uppdateras i bakgrunden."
		},
		[OpenTpwText.TextureDownloadTitle] = new[] { "Clarity Enhanced", "Clarity Forbedret", "Clarity Verbeterd", "Clarity Amélioré", "Clarity Verbessert", "Clarity 향상", "Clarity Ulepszone", "Clarity Mejorado", "Clarity Förbättrad" },
		[OpenTpwText.TextureDownloadHelp] = new[] {
			"Downloading the texture pack from GitHub. This is a large download. You can cancel and play offline; select Clarity in Options to resume later.",
			"Teksturpakken hentes fra GitHub. Det er en stor download. Du kan annullere og spille offline; vælg Clarity i Indstillinger for at fortsætte senere.",
			"Het texturepakket wordt gedownload van GitHub. Dit is een grote download. Annuleer om offline te spelen; kies later Clarity in Opties om verder te gaan.",
			"Téléchargement du pack depuis GitHub. Ce téléchargement est volumineux. Annulez pour jouer hors ligne ; choisissez Clarity dans Options pour reprendre plus tard.",
			"Das Texturpaket wird von GitHub geladen. Dies ist ein großer Download. Zum Offline-Spielen abbrechen; später Clarity in Optionen wählen, um fortzusetzen.",
			"GitHub에서 텍스처 팩을 내려받는 중입니다. 용량이 큽니다. 취소하고 오프라인으로 플레이할 수 있으며, 옵션에서 Clarity를 선택하면 나중에 이어집니다.",
			"Pobieranie pakietu tekstur z GitHub. To duży plik. Możesz anulować i grać offline; wybierz Clarity w Opcjach, aby wznowić później.",
			"Descargando el paquete de texturas de GitHub. Es una descarga grande. Puedes cancelar y jugar sin conexión; elige Clarity en Opciones para reanudar más tarde.",
			"Texturpaketet hämtas från GitHub. Det är en stor hämtning. Avbryt för att spela offline; välj Clarity i Inställningar för att fortsätta senare." },
