		[OpenTpwText.TpiPlaceHint] = new[] { "{0}: click the park to place it{1}; the Rotate button turns it, Esc puts it away.", "{0}: klik i parken for at placere den{1}; Drej-knappen drejer den, Esc lægger den væk.", "{0}: klik in het park om het te plaatsen{1}; met Draaien draai je het, met Esc berg je het op.", "{0} : cliquez dans le parc pour le placer{1} ; le bouton Pivoter le tourne, Échap le range.", "{0}: Klicke in den Park, um es zu platzieren{1}; mit der Drehen-Taste drehst du es, Esc legt es weg.", "{0}: 공원을 클릭해 놓으십시오{1}. 회전 버튼으로 돌리고 Esc로 치웁니다.", "{0}: kliknij w parku, aby to postawić{1}; przycisk Obróć obraca obiekt, Esc go chowa.", "{0}: haz clic en el parque para colocarlo{1}; el botón Girar lo gira, Esc lo guarda.", "{0}: klicka i parken för att placera den{1}; Rotera-knappen vrider den, Esc lägger undan den." },
