		[OpenTpwText.TpiMenuHeading] = new[] { "Theme Park Inc experimental slice", "Theme Park Inc eksperimentelt udsnit", "Theme Park Inc experimenteel deel", "Tranche expérimentale de Theme Park Inc", "Experimenteller Theme-Park-Inc-Ausschnitt", "Theme Park Inc 실험적 일부", "Eksperymentalny fragment Theme Park Inc", "Fragmento experimental de Theme Park Inc", "Theme Park Inc experimentell del" },
		[OpenTpwText.TpiLimits] = new[] { "experimental Theme Park Inc slice: money only (cash, loans, build and running costs, calendar); no staff, research, challenges, advisor, missions, Global Master Save, COS files, park saves or sharing, and no Theme Park Inc interface; none of it is checked against the original game", "eksperimentelt Theme Park Inc-udsnit: kun penge (kontanter, lån, bygge- og driftsomkostninger, kalender); ingen medarbejdere, forskning, udfordringer, rådgiver, missioner, Global Master Save, COS-filer, parkgemning eller deling, og ingen Theme Park Inc-brugerflade; intet af det er kontrolleret mod det originale spil", "experimenteel Theme Park Inc-deel: alleen geld (kas, leningen, bouw- en exploitatiekosten, kalender); geen personeel, onderzoek, uitdagingen, adviseur, missies, Global Master Save, COS-bestanden, parkopslag of delen, en geen Theme Park Inc-interface; niets hiervan is getoetst aan het originele spel", "tranche expérimentale de Theme Park Inc : argent seulement (trésorerie, prêts, coûts de construction et d'exploitation, calendrier) ; pas de personnel, de recherche, de défis, de conseiller, de missions, de Global Master Save, de fichiers COS, de sauvegardes ni de partage de parcs, et pas d'interface Theme Park Inc ; rien n'est vérifié par rapport au jeu d'origine", "experimenteller Theme-Park-Inc-Ausschnitt: nur das Geld (Kasse, Darlehen, Bau- und Betriebskosten, Kalender); kein Personal, keine Forschung, keine Herausforderungen, kein Berater, keine Missionen, kein Global Master Save, keine COS-Dateien, keine Park-Speicherstände und kein Teilen, und keine Theme-Park-Inc-Oberfläche; nichts davon wurde mit dem Originalspiel abgeglichen", "실험적 Theme Park Inc 일부: 돈만 작동합니다(현금, 대출, 건설·운영 비용, 달력). 직원, 연구, 도전 과제, 조언자, 임무, Global Master Save, COS 파일, 공원 저장과 공유가 없고 Theme Park Inc 인터페이스도 없습니다. 원작과 대조하지 않았습니다", "eksperymentalny fragment Theme Park Inc: tylko pieniądze (gotówka, pożyczki, koszty budowy i utrzymania, kalendarz); brak personelu, badań, wyzwań, doradcy, misji, Global Master Save, plików COS, zapisów parku i udostępniania oraz interfejsu Theme Park Inc; nic z tego nie jest sprawdzone z oryginalną grą", "fragmento experimental de Theme Park Inc: solo el dinero (efectivo, préstamos, costes de construcción y funcionamiento, calendario); sin personal, investigación, desafíos, asesor, misiones, Global Master Save, archivos COS, partidas guardadas del parque ni compartir, y sin interfaz de Theme Park Inc; nada se ha comprobado con el juego original", "experimentell Theme Park Inc-del: bara pengarna (kontanter, lån, bygg- och driftskostnader, kalender); ingen personal, forskning, utmaningar, rådgivare, uppdrag, Global Master Save, COS-filer, parksparning eller delning, och inget Theme Park Inc-gränssnitt; inget av det är kontrollerat mot originalspelet" },
		[OpenTpwText.TpiResume] = new[] { "Resume", "Fortsæt", "Hervatten", "Reprendre", "Weiter", "계속", "Wznów", "Reanudar", "Fortsätt" },
		[OpenTpwText.TpiSaveLayout] = new[] { "Save layout checkpoint", "Gem layout", "Indeling opslaan", "Sauvegarder le plan", "Layout-Speicherpunkt anlegen", "배치 체크포인트 저장", "Zapisz punkt kontrolny układu", "Guardar punto de diseño", "Spara layout" },
		[OpenTpwText.TpiLayoutSaved] = new[] { "Layout saved. Loading it starts a new session; guests, script progress and clock are not saved.", "Layout gemt. Ved indlæsning startes en ny session; gæster, scriptforløb og ur gemmes ikke.", "Indeling opgeslagen. Bij het laden begint een nieuwe sessie; bezoekers, scriptvoortgang en klok worden niet opgeslagen.", "Plan sauvegardé. Le charger démarre une nouvelle session ; les visiteurs, la progression des scripts et l'horloge ne sont pas sauvegardés.", "Layout gespeichert. Beim Laden beginnt eine neue Sitzung; Besucher, Skriptfortschritt und Uhr werden nicht gespeichert.", "배치를 저장했습니다. 불러오면 새 세션이 시작되며 손님, 스크립트 진행, 시계는 저장되지 않습니다.", "Układ zapisany. Wczytanie go zaczyna nową sesję; goście, postęp skryptów i zegar nie są zapisywane.", "Diseño guardado. Al cargarlo empieza una sesión nueva; los visitantes, el progreso de los scripts y el reloj no se guardan.", "Layout sparad. Vid inläsning startas en ny session; gäster, skriptframsteg och klocka sparas inte." },
