	public static IReadOnlyList<string> SupportedLanguages => Languages;

	/// <summary>The label in <paramref name="language"/>; English for languages without a translation.</summary>
	public static string Get( OpenTpwText key, string language )
	{
		var column = Array.FindIndex( Languages, name => string.Equals( name, language, StringComparison.OrdinalIgnoreCase ) );
		return table[key][Math.Max( 0, column )];
	}

	/// <summary>
	/// The name of <paramref name="language"/> to show in the language row: its own name ("한국어") when <paramref name="canDraw"/> says the
	/// current UI font draws every character of it, otherwise its English name ("Korean"), which every font draws. The row is shown
	/// in the language in use, so a Latin-only font would otherwise show Hangul as missing glyphs until the switch.
	/// </summary>
	public static string DisplayName( string language, Func<char, bool>? canDraw = null )
	{
		var own = LanguageNames.TryGetValue( language, out var name ) ? name : language;
		return canDraw == null || own.All( canDraw ) ? own : language;
	}

	/// <summary>Every text in <paramref name="language"/>, with the language names as the language row shows them (<see cref="DisplayName"/>).</summary>
	public static IEnumerable<string> AllTexts( string language, Func<char, bool>? canDraw = null ) =>
		Enum.GetValues<OpenTpwText>().Select( key => Get( key, language ) ).Concat( Languages.Select( name => DisplayName( name, canDraw ) ) );
}
